class T {
    static void f(int[] a) {
        try {
            a[3] = 1;
            System.out.print("1");
        } catch (ArithmeticException e) {
            System.out.print("2");
        } catch (Exception e) {
            System.out.print("3");
        } finally {
            System.out.print("4");
        }
        System.out.print("5");
    }
}

public class Main {
    public static void main(String[] args) {
        T.f(new int[3]);
    }
}

